// Create explicit Heap with SHARED | SHARED_CROSS_ADAPTER flags
ComPtr<ID3D12Heap> prodSharedHeap;
D3D12_HEAP_DESC heapDesc = {};
heapDesc.Properties = heapProps;
heapDesc.SizeInBytes = allocInfo.SizeInBytes;
heapDesc.Alignment = allocInfo.Alignment ? allocInfo.Alignment : 65536; // Ensure non-zero alignment
heapDesc.Flags = D3D12_HEAP_FLAG_SHARED | D3D12_HEAP_FLAG_SHARED_CROSS_ADAPTER;
hr = prodDevice->CreateHeap(&heapDesc, IID_PPV_ARGS(&prodSharedHeap));
if (FAILED(hr)) {
    PrintJson("FAIL", "CreateHeap SHARED|SHARED_CROSS_ADAPTER failed", &prodInfo->luid, &consInfo->luid,
              prodInfo->desc.DedicatedVideoMemory, prodInfo->desc.SharedSystemMemory,
              consInfo->desc.DedicatedVideoMemory, consInfo->desc.SharedSystemMemory, 0, kTransport, -1, hr);
    return 2;
}

